UPDATE passport_stamp_rules
SET name = #{name}, description = #{description}, condition_type = #{conditionType},
    threshold = #{threshold}, icon = #{icon}, reward_points = #{rewardPoints}, is_active = #{isActive}
WHERE code = #{code} AND version = #{version}

mapper.select:
SELECT COUNT(*)
FROM passport_events
WHERE user_id = #{userId} AND place_id = #{placeId}

SELECT COUNT(*)
FROM passport_tag_places
WHERE passport_tag_id = #{tagId}

SELECT COUNT(*)
FROM passport_tag_places tp
WHERE tp.passport_tag_id = #{tag.id}
  AND (
      SELECT COUNT(*)
      FROM passport_events e
      WHERE e.user_id = #{userId}
        AND e.place_id = tp.place_id
  ) >= COALESCE(#{tag.requiredCheckinCount}, 1)

SELECT COUNT(DISTINCT COALESCE(e.place_id::text, NULLIF(e.location_key, '')))
FROM passport_events e
JOIN passport_definition_provinces dp
  ON dp.passport_id = #{tag.passportId}
 AND dp.province_code = e.province_code
WHERE e.user_id = #{userId}

SELECT e.user_id, (array_agg(e.id ORDER BY e.occurred_at DESC))[1] AS triggering_event_id
FROM passport_events e
WHERE (
    EXISTS (
        SELECT 1 FROM passport_tag_places tp
        WHERE tp.passport_tag_id = #{tag.id} AND tp.place_id = e.place_id
    )
    OR (
        #{tag.qualificationMode} = 'PASSPORT_PROVINCES'
        AND
        NOT EXISTS (
            SELECT 1 FROM passport_tag_places any_link
            WHERE any_link.passport_tag_id = #{tag.id}
        )
        AND EXISTS (
            SELECT 1 FROM passport_definition_provinces dp
            WHERE dp.passport_id = #{tag.passportId}
              AND dp.province_code = e.province_code
        )
    )
    OR (
        #{tag.qualificationMode} = 'PASSPORT_LOCATIONS'
        AND NOT EXISTS (
            SELECT 1 FROM passport_tag_places any_link
            WHERE any_link.passport_tag_id = #{tag.id}
        )
        AND EXISTS (
            SELECT 1
            FROM passport_definition_location_images pdi
            JOIN location_images li ON li.id = pdi.location_image_id
            LEFT JOIN places p ON p.id = e.place_id
            WHERE pdi.passport_id = #{tag.passportId}
              AND li.latitude IS NOT NULL AND li.longitude IS NOT NULL
              AND COALESCE(p.latitude, e.latitude) IS NOT NULL
              AND COALESCE(p.longitude, e.longitude) IS NOT NULL
              AND 6371 * acos(LEAST(1, GREATEST(-1,
                  cos(radians(li.latitude)) * cos(radians(COALESCE(p.latitude, e.latitude))) *
                  cos(radians(COALESCE(p.longitude, e.longitude)) - radians(li.longitude)) +
                  sin(radians(li.latitude)) * sin(radians(COALESCE(p.latitude, e.latitude)))
              ))) <= #{locationRadiusKm}
        )
    )
)
GROUP BY e.user_id
HAVING (
    (
        EXISTS (
            SELECT 1 FROM passport_tag_places any_link
            WHERE any_link.passport_tag_id = #{tag.id}
        )
        AND NOT EXISTS (
            SELECT 1
            FROM passport_tag_places tp
            WHERE tp.passport_tag_id = #{tag.id}
              AND (
                  SELECT COUNT(*)
                  FROM passport_events e2
                  WHERE e2.user_id = e.user_id
                    AND e2.place_id = tp.place_id
              ) < COALESCE(#{tag.requiredCheckinCount}, 1)
        )
    )
    OR (
        NOT EXISTS (
            SELECT 1 FROM passport_tag_places any_link
            WHERE any_link.passport_tag_id = #{tag.id}
        )
        AND COUNT(DISTINCT COALESCE(e.place_id::text, NULLIF(e.location_key, ''))) >=
            COALESCE(#{tag.requiredCheckinCount}, 1)
    )
)

