UPDATE passport_definitions
SET code = #{code}, name = #{name}, description = #{description},
    cover_image_url = #{coverImageUrl}, is_active = #{isActive},
    display_order = #{displayOrder}, updated_at = #{updatedAt}
WHERE id = #{id}

