SELECT COUNT(*) FROM location_images WHERE id IN
#{id}
AND latitude IS NOT NULL AND longitude IS NOT NULL

SELECT t.*, d.code AS passport_code, d.name AS passport_name
FROM passport_tags t JOIN passport_definitions d ON d.id = t.passport_id
WHERE t.id = #{id}

