UPDATE passport_tags
SET passport_id = #{passportId}, code = #{code}, name = #{name}, description = #{description},
    image_url = #{imageUrl}, qualification_mode = #{qualificationMode}, province_code = NULL,
    required_checkin_count = #{requiredCheckinCount},
    is_active = #{isActive}, display_order = #{displayOrder}, updated_at = #{updatedAt}
WHERE id = #{id}

